DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.accept_household_invite(uuid,boolean)'::regprocedure) INTO definition; definition := replace(definition, 'INSERT INTO public.household_members(household_id,user_id,role) VALUES(inv.household_id,auth.uid(),''member'');', 'IF old_hid IS NOT NULL THEN DELETE FROM public.household_members WHERE household_id=old_hid AND user_id=auth.uid(); END IF; INSERT INTO public.household_members(household_id,user_id,role) VALUES(inv.household_id,auth.uid(),''member'');'); EXECUTE definition; END $$;